import { ClientDetail } from '../../slots/defs/clientDetail';
import { useSearchParam, asFlag } from '../../url/useSearchParam';
import { CLIENT_STATEMENT_PARAM } from './queries';
import { ClientStatementTable } from './ClientStatementTable';

// The statement panel on a client's detail page — one new *.slot.tsx file filling the ClientDetail
// region (CLAUDE.md rule 3). Nothing existing is edited to add it. The "open statement" control owns
// the `clientStatement` URL key (rule 4): whether the statement is open outlives a click, so it
// lives in the URL, and the panel reads the same key to decide whether to render the table.
function ClientStatementPanel({ clientId }: { clientId: number }) {
  const [open, setOpen] = useSearchParam(CLIENT_STATEMENT_PARAM, asFlag);
  return (
    <section data-testid="client-statement">
      <button
        type="button"
        data-testid="client-statement-open"
        onClick={() => setOpen(open ? undefined : true)}
      >
        Statement
      </button>
      {open ? <ClientStatementTable clientId={clientId} /> : null}
    </section>
  );
}

export const contribution = ClientDetail.fill({ order: 20, Component: ClientStatementPanel });

import { useQuery } from '@tanstack/react-query';
import { clientStatementKey, fetchClientStatement, type StatementInvoice } from './queries';
import { formatMoney } from '../../ui/money';

// A client's statement: all their invoices in one place with the total still owed. Queries for
// itself under ['clients', clientId, 'statement'] — never handed its data by a parent (CLAUDE.md
// rule 5). The per-invoice due and the total owed are derived server-side, so the headline figure
// always matches the rows.
export function ClientStatementTable({ clientId }: { clientId: number }) {
  const { data: statement } = useQuery({
    queryKey: clientStatementKey(clientId),
    queryFn: () => fetchClientStatement(clientId),
  });

  if (!statement) {
    return null;
  }

  return (
    <>
      <table data-testid="client-statement-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Status</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {statement.invoices.map((invoice: StatementInvoice) => (
            <tr key={invoice.id} data-testid={`statement-invoice-row-${invoice.id}`}>
              <td data-testid="statement-invoice-amount">{formatMoney(invoice.amount)}</td>
              <td data-testid="statement-invoice-status">{invoice.status}</td>
              <td data-testid="statement-invoice-due">{formatMoney(invoice.due)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p data-testid="client-outstanding-total">{formatMoney(statement.totalOwed)}</p>
    </>
  );
}

