1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.ArrayList;
5	import java.util.List;
6	import net.officefloor.web.HttpPathParameter;
7	import net.officefloor.web.ObjectResponse;
8	
9	/**
10	 * GET /api/clients/{clientId}/statement — one client's statement: every invoice raised for the
11	 * client (across all their projects), oldest id first, each with how much is still due, plus the
12	 * total the client still owes (the sum of those dues). Wired by
13	 * {@code officefloor/rest/api/clients/{clientId}/statement.GET.yml}.
14	 */
15	public class ClientStatementGet {
16	
17	    public void service(@HttpPathParameter("clientId") String clientId,
18	            InvoiceRepository invoices, PaymentRepository payments,
19	            ObjectResponse<ClientStatement> response) {
20	        List<ProjectInvoice> rows = new ArrayList<>();
21	        BigDecimal totalOwed = BigDecimal.ZERO;
22	        for (Invoice invoice : invoices.findByClientId(Long.valueOf(clientId))) {
23	            ProjectInvoice row = new ProjectInvoice(invoice, payments.sumByInvoiceId(invoice.getId()));
24	            rows.add(row);
25	            totalOwed = totalOwed.add(row.getDue());
26	        }
